<?php get_header(); ?>
<section class="archive-wrap"><div class="container"><header class="archive-header"><span class="section-kicker"><?php echo esc_html( make_t( 'MAKE journal', 'MAKE journal' ) ); ?></span><h1><?php echo esc_html( make_t( 'Ideas, guías y proyectos.', 'Ideas, guides and projects.' ) ); ?></h1></header><div class="content-grid"><?php if ( have_posts() ) : while ( have_posts() ) : the_post(); ?><article class="post-card"><a href="<?php the_permalink(); ?>"><div class="post-card-media"><?php if ( has_post_thumbnail() ) the_post_thumbnail( 'make-journal' ); ?></div><div class="post-card-body"><span class="section-kicker"><?php echo esc_html( make_reading_time( get_the_ID() ) ); ?></span><h2><?php the_title(); ?></h2><p><?php echo esc_html( wp_trim_words( get_the_excerpt(), 20 ) ); ?></p></div></a></article><?php endwhile; else : ?><p><?php echo esc_html( make_t( 'Todavía no hay contenido.', 'Nothing here yet.' ) ); ?></p><?php endif; ?></div><div class="pagination"><?php the_posts_pagination(); ?></div></div></section>
